#include <stdio.h>

int main(void)
{
    int c = 0;
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 3; j++) {
            c++;
        }
    }
    printf("%d\n", c);
    return 0;
}

#include <stdio.h>

int main(void)
{
    for (int row = 1; row <= 3; row++) {
        for (int col = 1; col <= row; col++) {
            printf("*");
        }
    }
    puts("");
    return 0;
}

#include <stdio.h>

int main(void)
{
    for (int row = 1; row <= 2; row++) {
        for (int col = 1; col <= 2; col++) {
            printf("%d", col);
        }
        puts("");
    }
    return 0;
}

