A two-by-three rectangle increments count per cell. What total appears?
#include <stdio.h>

int main(void)
{
    int c = 0;
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 3; j++) {
            c++;
        }
    }
    printf("%d\n", c);
    return 0;
}
